-- Batch and serial numbers, and work-in-process accounting for production.

-- SDK OBTN / OIBT / IBT1: batch master, batch quantity per warehouse, and the
-- batch rows of each stock posting (Direction 0 = in, 1 = out).
CREATE TABLE IF NOT EXISTS "OBTN" (
  "AbsEntry" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ItemCode" TEXT NOT NULL REFERENCES "OITM"("ItemCode"), "SysNumber" INTEGER NOT NULL, "DistNumber" TEXT NOT NULL,
  "MnfSerial" TEXT, "LotNumber" TEXT, "ExpDate" DATE, "MnfDate" DATE, "InDate" DATE DEFAULT CURRENT_DATE, "Notes" TEXT,
  UNIQUE ("ItemCode", "DistNumber"), UNIQUE ("ItemCode", "SysNumber")
);
CREATE TABLE IF NOT EXISTS "OIBT" (
  "ItemCode" TEXT NOT NULL, "BatchNum" TEXT NOT NULL, "WhsCode" TEXT NOT NULL REFERENCES "OWHS"("WhsCode"),
  "SysNumber" INTEGER, "Quantity" NUMERIC(19,6) DEFAULT 0, "ExpDate" DATE, "InDate" DATE DEFAULT CURRENT_DATE,
  PRIMARY KEY ("ItemCode", "BatchNum", "WhsCode")
);
CREATE TABLE IF NOT EXISTS "IBT1" (
  "LogEntry" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ItemCode" TEXT NOT NULL, "BatchNum" TEXT NOT NULL, "WhsCode" TEXT NOT NULL, "SysNumber" INTEGER,
  "BaseType" INTEGER NOT NULL, "BaseEntry" INTEGER NOT NULL, "BaseLinNum" INTEGER, "Quantity" NUMERIC(19,6) NOT NULL,
  "Direction" INTEGER NOT NULL CHECK ("Direction" IN (0, 1)), "DocDate" DATE
);
CREATE INDEX IF NOT EXISTS "IX_IBT1_Base" ON "IBT1" ("BaseType", "BaseEntry");

-- SDK OSRN / OSRQ / OSRI / SRI1: serial master, serial quantity per warehouse,
-- serial status (0 available, 1 unavailable) and the serial rows of each posting.
CREATE TABLE IF NOT EXISTS "OSRN" (
  "AbsEntry" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ItemCode" TEXT NOT NULL REFERENCES "OITM"("ItemCode"), "SysNumber" INTEGER NOT NULL, "DistNumber" TEXT NOT NULL,
  "MnfSerial" TEXT, "LotNumber" TEXT, "ExpDate" DATE, "MnfDate" DATE, "InDate" DATE DEFAULT CURRENT_DATE, "Notes" TEXT,
  UNIQUE ("ItemCode", "DistNumber"), UNIQUE ("ItemCode", "SysNumber")
);
CREATE TABLE IF NOT EXISTS "OSRQ" (
  "ItemCode" TEXT NOT NULL, "SysNumber" INTEGER NOT NULL, "WhsCode" TEXT NOT NULL REFERENCES "OWHS"("WhsCode"),
  "Quantity" NUMERIC(19,6) DEFAULT 0, PRIMARY KEY ("ItemCode", "SysNumber", "WhsCode")
);
CREATE TABLE IF NOT EXISTS "OSRI" (
  "ItemCode" TEXT NOT NULL, "SysSerial" INTEGER NOT NULL, "IntrSerial" TEXT NOT NULL, "SuppSerial" TEXT,
  "WhsCode" TEXT, "Status" INTEGER DEFAULT 0, "InDate" DATE DEFAULT CURRENT_DATE, "ExpDate" DATE,
  PRIMARY KEY ("ItemCode", "SysSerial")
);
CREATE TABLE IF NOT EXISTS "SRI1" (
  "LogEntry" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ItemCode" TEXT NOT NULL, "SysSerial" INTEGER NOT NULL, "IntrSerial" TEXT, "WhsCode" TEXT NOT NULL,
  "BaseType" INTEGER NOT NULL, "BaseEntry" INTEGER NOT NULL, "BaseLinNum" INTEGER,
  "Direction" INTEGER NOT NULL CHECK ("Direction" IN (0, 1)), "DocDate" DATE
);
CREATE INDEX IF NOT EXISTS "IX_SRI1_Base" ON "SRI1" ("BaseType", "BaseEntry");

-- G/L Account Determination: WIP inventory and WIP variance (after the
-- warehouse's own accounts). A company on the starter chart (it has 120000
-- Inventory) gets "Work in Process" and "Production Variances": an existing
-- account with that name is reused, otherwise one is added at the first free
-- code. Any other chart sets them in setup.
ALTER TABLE "OACP"
  ADD COLUMN IF NOT EXISTS "WipAcct" TEXT REFERENCES "OACT"("AcctCode"),
  ADD COLUMN IF NOT EXISTS "WipVarAcct" TEXT REFERENCES "OACT"("AcctCode");
DO $$
DECLARE
  spec RECORD;
  code TEXT;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM "OACT" WHERE "AcctCode" = '120000') THEN RETURN; END IF;
  FOR spec IN SELECT * FROM (VALUES
    ('WipAcct', 'Work in Process', 1, ARRAY['125000', '125100', '125900', '129000']),
    ('WipVarAcct', 'Production Variances', 5, ARRAY['530000', '535000', '539000', '590000'])
  ) AS s(col, title, grp, codes) LOOP
    SELECT "AcctCode" INTO code FROM "OACT" WHERE "AcctName" = spec.title ORDER BY "AcctCode" LIMIT 1;
    IF code IS NULL THEN
      SELECT u.c INTO code FROM unnest(spec.codes) WITH ORDINALITY AS u(c, n)
        WHERE NOT EXISTS (SELECT 1 FROM "OACT" WHERE "AcctCode" = u.c) ORDER BY u.n LIMIT 1;
      IF code IS NOT NULL THEN
        INSERT INTO "OACT" ("AcctCode", "AcctName", "GroupMask", "FormatCode") VALUES (code, spec.title, spec.grp, code);
      END IF;
    END IF;
    IF code IS NOT NULL THEN
      EXECUTE format('UPDATE "OACP" SET %I = COALESCE(%I, $1)', spec.col, spec.col) USING code;
    END IF;
  END LOOP;
END $$;

-- Closing a production order links its WIP variance journal entry.
ALTER TABLE "OWOR" ADD COLUMN IF NOT EXISTS "TransId" INTEGER;
